<div class="shell"><header class="brandbar"><div class="brand"><div class="mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 10v4m4-7v10m4-14v18m4-14v10m4-7v4"/></svg></div><div><h1>Transcripted</h1><small>Your meeting, within reach.</small></div></div><div class="connection"><i id="connection-dot" class="dot"></i><span id="connection-label">Connecting</span><button id="refresh" class="quiet icon-button" aria-label="Refresh connection" disabled>↻</button></div></header>
<div class="nav" role="tablist" aria-label="Companion"><button id="tab-live" class="tab" role="tab" aria-selected="true" aria-controls="live-page">Meeting</button><button id="tab-context" class="tab" role="tab" aria-selected="false" aria-controls="context-page">Saved context <span id="context-count"></span></button></div>
<section id="live-page" role="tabpanel" aria-labelledby="tab-live"><div class="card recording-card"><div><p class="eyebrow">Current meeting</p><div class="state-line"><i id="recording-dot" class="dot"></i><h2 id="recording-title">Connect to Transcripted</h2></div><p id="recording-hint" class="state-hint">Open the Mac app and enable the companion in Settings → Agent.</p></div><div class="controls"><time id="elapsed" class="elapsed" hidden aria-label="Recording duration">0:00</time><button id="start" class="primary" disabled>Start meeting</button><button id="stop" class="stop" disabled hidden>Stop &amp; save</button></div></div>
<label class="card share-card" for="share"><div class="share-copy"><strong>Share with chat</strong><p id="sharing-hint">Off for every new meeting. Turning this on sends provisional text to this ChatGPT view and adds a bounded recent passage to chat context.</p></div><input id="share" class="toggle" type="checkbox" disabled aria-describedby="sharing-hint"></label>
<div class="section-heading"><h3>Live transcript</h3><span class="badge">Local preview · provisional</span></div><div id="live-transcript" class="card transcript" aria-label="Live transcript"><div class="empty"><div class="empty-symbol" aria-hidden="true">≋</div><h3 id="live-empty-title">Keep the conversation flowing.</h3><p id="live-empty-text">Start a meeting, then choose whether to share live text here.</p></div></div><div class="reading-actions"><button id="follow-live" class="quiet" hidden>Jump to latest</button></div><div class="live-footer"><span id="live-update">Live text stays private until you enable sharing.</span><span>Final speaker labels appear in the saved transcript.</span></div>
</section>
<section id="context-page" role="tabpanel" aria-labelledby="tab-context" hidden><form id="search-form" class="context-header"><div class="search"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="8" cy="8" r="5"/><path d="m12 12 5 5"/></svg><input id="query" placeholder="Find a decision, a person, a phrase…" aria-label="Search saved context" maxlength="300"></div><select id="kind" aria-label="Capture type"><option value="all">Everything</option><option value="meeting">Meetings</option><option value="dictation">Dictations</option><option value="writing">Writing</option></select><button id="search-button" type="submit" disabled>Search</button></form><div class="context-grid"><nav class="context-list" id="context-list" aria-label="Saved captures"><p class="muted">Waiting for your saved context.</p></nav><div class="card passage-pane"><div id="passage-empty" class="empty"><div class="empty-symbol" aria-hidden="true">↗</div><h3>A little context goes a long way.</h3><p>Select a capture to read a passage. Attach just what matters to your conversation.</p></div><div id="passage-detail" hidden><p id="passage-kind" class="eyebrow"></p><h2 id="passage-title"></h2><p id="passage-meta" class="passage-meta"></p><blockquote id="passage-text" class="passage-text"></blockquote><p id="passage-truncated" class="muted" hidden>Showing the first 4,000 characters of this passage.</p><div class="paging"><button id="previous" disabled aria-label="Previous passage">←</button><small id="passage-position"></small><button id="next" disabled aria-label="Next passage">→</button></div><div class="passage-actions"><button id="attach" class="primary" disabled>Attach passage</button><button id="ask" disabled>Ask about this</button><button id="remove-context" class="quiet" disabled hidden>Remove attachment</button></div><p id="attachment-state" class="attached">Nothing attached to chat</p><div class="source-row"><a id="source" href="#" aria-disabled="true">Open source passage ↗</a><span> · Saved locally in Transcripted</span></div></div></div></div></section>
<p id="notice" class="notice" role="status" aria-live="polite">Connecting to the ChatGPT host…</p><details class="privacy-details"><summary>Audio stays on your Mac · About sharing</summary><p class="privacy-note">Capture and speech recognition run on your Mac. Selected context and explicitly shared live text are sent to ChatGPT. No audio is uploaded by this companion. Turning sharing off stops new text; it does not remove text already sent in chat.</p></details>
</div>
<script>(()=>{'use strict';
const $=id=>document.getElementById(id), pending=new Map();
const state={host:false,disposed:false,capabilities:{},native:{connected:false},items:[],selected:null,busy:false,loading:false,generation:0,listingGeneration:0,sessionGeneration:0,actionEpoch:0,sharingPaused:false,pendingSharing:null,live:[],liveInfo:{},sequence:0,lastTextAt:0,pollTimer:null,polling:false,attachment:null,attachedSelection:null,attachedKind:null,contextRevision:0,desiredContext:null,inFlightContext:null,contextWriting:false,nextDeepLink:null,requestedDisplay:false,followLive:true};let requestID=0;
const supported=x=>x!==null&&typeof x==='object', tools=()=>state.host&&supported(state.capabilities.serverTools), context=()=>state.host&&supported(state.capabilities.updateModelContext?.text), messages=()=>state.host&&supported(state.capabilities.message?.text), active=()=>state.native.capture_active===true&&typeof state.native.session_id==='string';
const key=p=>p?`${p.kind}/${p.filename}/${p.entry_id||''}/${p.passage_index}`:null;
const sharing=()=>active()&&state.native.sharing_enabled===true&&!state.sharingPaused;
function revokeLiveContext(){if(state.attachedKind==='live'||state.desiredContext?.kind==='live'||state.inFlightContext?.kind==='live')queueContext(null,'clear')}
const liveStatusText=info=>info.live_status==='unavailable'?(info.error_code==='model_unavailable'?'Live speech model unavailable. Check Transcripted on your Mac.':'Live preview unavailable. Check Transcripted on your Mac.'):({waiting_for_model:'Loading the local speech model…',model_unavailable:'Live speech model unavailable. Check Transcripted on your Mac.',paused_for_other_transcription:'Live preview is paused while another local transcription finishes.',retrying:'Live preview is retrying after a local processing error.',starting:'Starting the local live preview…',disabled:'Live preview is disabled.'}[info.live_status]||null);
