function send(message){if(!state.disposed)window.parent.postMessage({jsonrpc:'2.0',...message},'*')}
function request(method,params={},timeout=12000){if(state.disposed||window.parent===window)return Promise.reject(new Error('Open this companion in a supported ChatGPT host.'));const id=++requestID;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(new Error('Transcripted did not reply. Refresh its status before retrying a recording action.'))},timeout);pending.set(id,{resolve,reject,timer});send({id,method,params})})}
function checked(result){if(result?.isError)throw new Error(result.content?.filter(b=>b.type==='text').map(b=>b.text).join('\n')||'Transcripted declined the action.');return result}
async function tool(name,args={}){if(!tools())throw new Error('This host has not advertised companion tool calls.');return checked(await request('tools/call',{name,arguments:args},name==='start_meeting'||name==='stop_meeting'?42000:12000))}
const payload=result=>result?._meta?.['transcripted/companion']||{};
function resize(){if(state.host)send({method:'ui/notifications/size-changed',params:{height:Math.ceil(document.body.getBoundingClientRect().height)}})}
function controls(){const free=tools()&&!state.busy;const live=active();$('refresh').disabled=!free;$('start').hidden=live;$('start').disabled=!free||state.native.connected===false||state.native.allow_meeting_control!==true||state.native.capture_active===true;$('stop').hidden=!live;$('stop').disabled=!free||state.native.allow_meeting_control!==true;$('share').checked=state.pendingSharing!==null?state.pendingSharing:live&&state.native.sharing_enabled===true;$('share').disabled=!free||!live||state.native.allow_live_sharing!==true||!context();$('search-button').disabled=!free;$('previous').disabled=!free||state.loading||!state.selected||state.selected.passage_index===0;$('next').disabled=!free||state.loading||!state.selected||state.selected.passage_index+1>=state.selected.total_passages;$('attach').disabled=!free||state.loading||!state.selected||!context();$('ask').disabled=!free||state.loading||!state.selected||!messages();$('remove-context').hidden=!state.attachment;$('remove-context').disabled=!free||!context();$('source').setAttribute('aria-disabled',!supported(state.capabilities.openLinks)||!state.selected?'true':'false')}
function applyStatus(status){if(!status||typeof status!=='object')return;const previous=state.native.session_id;state.native={...status,connected:status.connected!==false};state.liveInfo={...state.liveInfo,error_code:null,...status};if(previous!==status.session_id){state.sessionGeneration++;state.followLive=true;state.sharingPaused=false;state.sequence=0;state.live=[];state.liveInfo={error_code:null,...status};state.lastTextAt=0;revokeLiveContext();renderLive()}
const online=state.native.connected!==false;$('connection-dot').className='dot'+(online?' connected':'');$('connection-label').textContent=online?'Connected':'Disconnected';const running=active();$('recording-dot').className='dot'+(running?' recording pulse':'');
$('elapsed').hidden=!running;$('elapsed').textContent=stamp(status.capture_elapsed_seconds);const rs=status.recording_state||status.state||'ready';$('recording-title').textContent=!online?'Connect to Transcripted':rs==='error'?'Needs attention in Transcripted':rs==='loading_models'?'Loading local models…':running?(rs==='stopping_recording'?'Finishing meeting…':'Recording in Transcripted'):rs==='transcribing'?'Processing saved transcript':rs==='starting_recording'?'Starting recording…':'Ready when you are';
$('recording-hint').textContent=!online?(status.message||'Open Transcripted and enable the companion in Settings → Agent.'):rs==='error'?'Open the Mac app to check the capture error and its recovery options.':rs==='loading_models'?'Transcripted is preparing the selected on-device models.':running?'Stop & save finishes the capture and queues your final transcript.':status.allow_meeting_control!==true?'Allow meeting controls in Transcripted Settings → Agent to record here.':rs==='transcribing'?'The final transcript is being processed locally. Refresh saved context when it is ready.':'Microphone and meeting audio are captured by the Mac app.';
