function applyInitial(result){const data=payload(result);if(data.status)applyStatus(data.status);if(Array.isArray(data.items))applyItems(data.items);if(data.passage)applyPassage(data.passage);if(data.live)applyLive(data.live)}
async function refreshStatus(){try{const result=await tool('get_recording_status');applyStatus(result.structuredContent);notice('Connection refreshed.')}catch(error){applyStatus({connected:false,state:'offline',message:error.message});notice(error.message,true)}}
function schedulePoll(){clearTimeout(state.pollTimer);if(state.disposed||!tools()||!active())return;state.pollTimer=setTimeout(poll,3500)}
async function poll(){if(state.polling||state.busy){schedulePoll();return}state.polling=true;const generation=state.sessionGeneration,epoch=state.actionEpoch;try{const result=await tool('get_recording_status');if(generation!==state.sessionGeneration||epoch!==state.actionEpoch)return;applyStatus(result.structuredContent);if(sharing()){const session=state.native.session_id,readGeneration=state.sessionGeneration;const live=payload(await tool('read_live_transcript',{session_id:session,after_sequence:state.sequence,limit:30})).live;if(readGeneration===state.sessionGeneration&&epoch===state.actionEpoch&&session===state.native.session_id&&sharing())applyLive(live)}}catch(error){if(generation===state.sessionGeneration&&epoch===state.actionEpoch){notice(error.message,true);$('live-update').textContent='Connection interrupted. Live context updates paused.';applyStatus({connected:false,state:'offline',message:error.message})}}finally{state.polling=false;schedulePoll()}}
function stamp(seconds){const value=Math.max(0,Math.floor(Number(seconds)||0));return `${Math.floor(value/60)}:${String(value%60).padStart(2,'0')}`}
function renderLive(){const box=$('live-transcript'),scrollBefore=box.scrollTop;const renderKey=JSON.stringify([state.native.session_id,active(),sharing(),state.sharingPaused,liveStatusText(state.liveInfo),state.live.map(s=>[s.sequence,s.start_seconds,s.source,s.text])]);if(state.renderKey!==renderKey){state.renderKey=renderKey;box.replaceChildren();if(!state.live.length){const empty=document.createElement('div');empty.className='empty';const icon=document.createElement('div');icon.className='empty-symbol';icon.textContent='≋';const title=document.createElement('h3');const text=document.createElement('p');if(!active()){title.textContent='Keep the conversation flowing.';text.textContent='Start a meeting, then choose whether to share live text here.'}else if(!sharing()){title.textContent=state.sharingPaused?'Live updates paused.':'This meeting is private.';text.textContent=state.sharingPaused?'No new text is being attached here. Check the Mac app if a sharing change failed.':'Enable live sharing to bring provisional text into ChatGPT.'}else{title.textContent=liveStatusText(state.liveInfo)||'Listening for the next passage…';text.textContent='Local speech recognition works in short windows. The final saved transcript remains authoritative.'}empty.append(icon,title,text);box.append(empty)}else{for(const segment of state.live){const row=document.createElement('div');row.className='utterance';const time=document.createElement('time');time.textContent=stamp(segment.start_seconds);const body=document.createElement('div');const label=document.createElement('span');label.className='speaker';label.textContent=segment.source==='microphone'?'Microphone':'Meeting audio';const text=document.createElement('p');text.textContent=segment.text;body.append(label,text);row.append(time,body);box.append(row)}box.scrollTop=state.followLive?box.scrollHeight:scrollBefore}$('follow-live').hidden=state.followLive||!state.live.length;}
let update=!active()?'Live text stays private until you enable sharing.':!sharing()?'No new live text is attached here.':liveStatusText(state.liveInfo)||(state.lastTextAt&&Date.now()-state.lastTextAt>60000?'Waiting for newer speech — the live transcript may be delayed.':state.live.length?'Live text shared · provisional.':'Waiting for locally recognized speech.');if(sharing()&&state.liveInfo.context_gap)update+=' Earlier live text is outside this view.';if(sharing()&&Number(state.liveInfo.dropped_windows)>0)update+=` ${state.liveInfo.dropped_windows} preview windows skipped; use the final saved transcript for a complete record.`;if(sharing()&&Number(state.liveInfo.preview_lag_seconds)>=20&&Number(state.liveInfo.pending_windows)>0)update+=` Preview about ${Math.round(state.liveInfo.preview_lag_seconds)}s behind (${state.liveInfo.pending_windows} queued windows).`;$('live-update').textContent=update}
function applyLive(live){if(!live||live.session_id!==state.native.session_id||live.sharing_enabled!==true||!sharing())return;state.liveInfo={...state.liveInfo,error_code:null,...live};const fresh=(Array.isArray(live.segments)?live.segments:[]).filter(s=>Number.isInteger(s.sequence)&&s.sequence>state.sequence&&typeof s.text==='string');if(fresh.length){state.live.push(...fresh);state.live=state.live.slice(-60);state.sequence=Math.max(state.sequence,...fresh.map(s=>s.sequence));state.lastTextAt=Date.now()}renderLive();if(context()&&state.live.length)queueLiveContext();if(live.truncated)notice('The live view shows a bounded passage. More text will load on the next update.');resize()}
function liveContextMetadata(){const output={};for(const name of ['snapshot_at_unix_seconds','session_started_at_unix_seconds','latest_text_at_unix_seconds','capture_elapsed_seconds','latest_text_audio_end_seconds','preview_lag_seconds','pending_windows','dropped_windows','dropped_audio_buffers','first_sequence','latest_sequence']){const value=state.liveInfo[name];if(value===null||typeof value==='number'&&Number.isFinite(value)&&value>=0)output[name]=value}if(typeof state.liveInfo.context_gap==='boolean')output.context_gap=state.liveInfo.context_gap;for(const name of ['live_status','error_code']){const value=state.liveInfo[name];if(value===null)output[name]=null;else if(typeof value==='string'&&/^[a-z_]{1,64}$/.test(value))output[name]=value}return output}
function queueLiveContext(){if(!sharing()||!state.live.length)return;const segments=state.live.slice(-20);let budget=6000;const bounded=[];for(let i=segments.length-1;i>=0&&budget>0;i--){const s=segments[i];const text=s.text.slice(-Math.min(2000,budget));bounded.unshift({sequence:s.sequence,start_seconds:s.start_seconds,source:s.source,text,provisional:true});budget-=text.length}queueContext({session_id:state.native.session_id,provisional:true,partial_window:true,attached_first_sequence:bounded[0]?.sequence,attached_last_sequence:bounded[bounded.length-1]?.sequence,metadata:liveContextMetadata(),segments:bounded},'live')}
// Serialize replacement context so an older asynchronous update cannot overwrite a newer selection.
function queueContext(data,kind){state.desiredContext={data,kind,revision:++state.contextRevision};drainContext()}
async function drainContext(){if(state.contextWriting||state.disposed||!context())return;state.contextWriting=true;try{while(state.desiredContext&&!state.disposed){const current=state.desiredContext;state.desiredContext=null;state.inFlightContext=current;const params=current.data?{content:[{type:'text',text:(current.kind==='live'?'Provisional live Transcripted context (final saved text may differ):\n':'Selected saved Transcripted passage:\n')+JSON.stringify(current.data),_meta:{'openai/title':current.kind==='live'?'Transcripted · Live meeting':current.data.title||'Transcripted passage'}}]}:{content:[]};if(current.data&&supported(state.capabilities.updateModelContext?.structuredContent))params.structuredContent=current.kind==='live'?{live_meeting:current.data}:{selected_passage:current.data};await request('ui/update-model-context',params);state.inFlightContext=null;if(current.revision===state.contextRevision){state.attachedKind=current.data?current.kind:null;state.attachedSelection=current.kind==='saved'?key(current.data):null;$('attachment-state').textContent=current.data?(current.kind==='live'?'Live meeting context attached':'Passage sent to host · attachment confirmation pending'):'Attachment cleared';}}}catch(error){notice(error.message,true)}finally{state.inFlightContext=null;state.contextWriting=false;controls();if(state.desiredContext)drainContext()}}
function applyItems(items){state.items=items.filter(i=>i&&typeof i.filename==='string'&&['meeting','dictation','writing'].includes(i.kind));$('context-count').textContent=state.items.length||'';renderItems();if(state.nextDeepLink)followDeepLink()}
function renderItems(){const list=$('context-list');list.replaceChildren();if(!state.items.length){const p=document.createElement('p');p.className='muted';p.textContent='No matching captures. Try a different phrase or capture type.';list.append(p)}for(const item of state.items){const button=document.createElement('button');button.className='context-item';button.setAttribute('aria-pressed',state.selected?.filename===item.filename&&state.selected?.kind===item.kind?'true':'false');const kind=document.createElement('span');kind.className='kind';kind.textContent=item.kind;const title=document.createElement('strong');title.textContent=item.title||item.filename;const meta=document.createElement('small');meta.textContent=item.date||'';button.append(kind,title,meta);if(item.preview){const p=document.createElement('p');p.className='preview';p.textContent=item.preview;button.append(p)}button.addEventListener('click',()=>selectPassage(item,0));list.append(button)}}
function validSource(p){try{const url=new URL(p.source_url);if(url.protocol!=='codex:'||url.host!=='plugins'||url.pathname!=='/transcripted@transcripted-local/app/show_companion'||url.hash||url.username||url.password)return false;const raw=url.searchParams.get('path');if(!raw?.startsWith('/')||raw.startsWith('//'))return false;const route=new URL(raw,'https://transcripted.invalid');return route.origin==='https://transcripted.invalid'&&route.pathname==='/context'&&route.searchParams.get('kind')===p.kind&&route.searchParams.get('filename')===p.filename&&route.searchParams.get('passage')===String(p.passage_index)}catch{return false}}
function applyPassage(p){if(!p||typeof p.text!=='string'||p.text.length>4000||!Number.isInteger(p.passage_index)||!Number.isInteger(p.total_passages)||p.passage_index<0||p.passage_index>=p.total_passages||!validSource(p))throw new Error('Transcripted returned an invalid source passage.');state.selected=p;$('passage-empty').hidden=true;$('passage-detail').hidden=false;$('passage-kind').textContent=p.kind;$('passage-title').textContent=p.title||p.filename;$('passage-meta').textContent=[p.speaker,typeof p.start_seconds==='number'?stamp(p.start_seconds):null].filter(Boolean).join(' · ');$('passage-text').textContent=p.text;$('passage-truncated').hidden=!p.truncated;$('passage-position').textContent=`Passage ${p.passage_index+1} of ${p.total_passages}`;$('source').href=p.source_url;$('attachment-state').textContent=state.attachedSelection===key(p)?'This passage is attached to chat':'This passage has not been attached';controls();renderItems();resize()}
async function selectPassage(item,index){if(!tools()||state.busy)return;const generation=++state.generation;state.loading=true;controls();notice('Loading the selected passage…');try{const args={kind:item.kind,filename:item.filename,passage_index:index};if(item.entry_id)args.entry_id=item.entry_id;const result=await tool('read_context_passage',args);if(generation===state.generation){const passage=payload(result).passage;if(passage?.kind!==args.kind||passage?.filename!==args.filename||passage?.passage_index!==index)throw new Error('The source changed while loading. Please select it again.');applyPassage(passage);notice('Passage loaded. Attach only what matters to this chat.')}}catch(error){if(generation===state.generation)notice(error.message,true)}finally{if(generation===state.generation){state.loading=false;controls()}}}
async function browse(){const generation=++state.listingGeneration;notice('Searching your saved context…');try{const result=await tool('browse_companion_context',{query:$('query').value.trim(),kind:$('kind').value});if(generation===state.listingGeneration){applyItems(payload(result).items||[]);notice('Select a passage to bring it into the conversation.')}}catch(error){if(generation===state.listingGeneration)notice(error.message,true)}}
async function action(callback){if(state.busy)return;state.actionEpoch++;state.busy=true;controls();try{await callback()}catch(error){notice(error.message,true)}finally{state.busy=false;controls();schedulePoll()}}
function tab(which){for(const name of ['live','context']){$('tab-'+name).setAttribute('aria-selected',String(name===which));$('tab-'+name).tabIndex=name===which?0:-1;$(name+'-page').hidden=name!==which}resize()}
function followDeepLink(){const link=state.nextDeepLink;state.nextDeepLink=null;try{if(typeof link?.url!=='string'||!link.url.startsWith('/')||link.url.startsWith('//'))throw new Error('Invalid source link.');const route=new URL(link.url,'https://transcripted.invalid');if(route.pathname==='/')return;if(route.origin!=='https://transcripted.invalid'||route.pathname!=='/context')throw new Error('This source is not a Transcripted passage.');const raw=route.searchParams.get('passage')||'0';if(!/^\d+$/.test(raw))throw new Error('Invalid passage index.');const kind=route.searchParams.get('kind'),filename=route.searchParams.get('filename');if(!['meeting','dictation','writing'].includes(kind)||!filename)throw new Error('Invalid source capture.');tab('context');selectPassage({kind,filename,entry_id:route.searchParams.get('entry_id')},Number(raw))}catch(error){notice(error.message,true)}}
function hostUpdate(update){if(!update||typeof update!=='object')return;if(update.theme==='dark'||update.theme==='light')document.documentElement.dataset.theme=update.theme;for(const [name,value]of Object.entries(update.styles?.variables||{}))if(name.startsWith('--')&&typeof value==='string')document.documentElement.style.setProperty(name,value);if(update['openai/interactionCursor'])document.documentElement.style.setProperty('--cursor-interaction',update['openai/interactionCursor']==='default'?'default':'pointer');if(Object.hasOwn(update,'openai/modelContext')){state.attachment=update['openai/modelContext']?.updateId||null;const selected=update['openai/modelContext']?.structuredContent?.selected_passage;if(selected)state.attachedSelection=key(selected);if(!state.attachment){state.attachedKind=null;state.attachedSelection=null}$('attachment-state').textContent=state.attachment?(state.attachedSelection===key(state.selected)?'This passage is attached to chat':'Context attached to chat'):'Nothing attached to chat'}if(update['openai/deepLink']){state.nextDeepLink=update['openai/deepLink'];if(tools()&&state.items.length)followDeepLink()}if(!state.requestedDisplay&&update.displayMode==='inline'&&update.availableDisplayModes?.includes('fullscreen')){state.requestedDisplay=true;request('ui/request-display-mode',{mode:'fullscreen'}).catch(()=>{})}controls();resize()}
function dispose(){state.disposed=true;clearTimeout(state.pollTimer);for(const item of pending.values()){clearTimeout(item.timer);item.reject(new Error('The companion view closed.'))}pending.clear();observer?.disconnect()}
window.addEventListener('message',event=>{if(event.source!==window.parent||state.disposed)return;const message=event.data;if(!message||message.jsonrpc!=='2.0')return;if(message.id!==undefined&&pending.has(message.id)){const item=pending.get(message.id);pending.delete(message.id);clearTimeout(item.timer);message.error?item.reject(new Error(message.error.message||'The host declined this action.')):item.resolve(message.result);return}try{if(message.method==='ui/notifications/tool-result')applyInitial(message.params);else if(message.method==='ui/notifications/host-context-changed')hostUpdate(message.params);else if(message.method==='ui/resource-teardown'){send({id:message.id,result:{}});dispose()}}catch(error){notice(error.message,true)}});
