$('share').onchange=()=>{if(state.busy){controls();return}const enabled=$('share').checked;state.pendingSharing=enabled;action(async()=>{const session=state.native.session_id;if(!enabled){state.sharingPaused=true;revokeLiveContext();state.live=[];renderLive()}try{const result=await tool('set_live_context_sharing',{session_id:session,enabled});if(enabled&&result.structuredContent?.sharing_enabled===true)state.sharingPaused=false;applyStatus(result.structuredContent);notice(result.structuredContent?.sharing_enabled===true?'Live text sharing enabled for this meeting.':'Live sharing off. New text will not be sent. Existing chat text remains.')}finally{state.pendingSharing=null;controls()}})};
